<script setup>



import {computed, ref, watch} from 'vue'
import QueryResults from '../shared/components/QueryResults.vue'
import {quoteIdentifier} from './browserModel.js'
import {emptyDataOptions, copyOptions, filterOperators, tableDataSQL} from './databaseQuery.js'
const props=defineProps({state:Object,target:Object,execute:Function,disabled:Boolean,approval:Boolean,consoleMode:Boolean,navigationOpen:{type:Boolean,default:true}})
const emit=defineEmits(['sql','browse','schema','close-navigation'])
const s=props.state,filter=ref(''),pending=ref(false),message=ref(''),navigationMessage=ref(''),resultFocused=ref(false)
Object.assign(s,{tables:[],tablesLoaded:false,table:'',view:'data',offset:0,result:null,schemas:{},previous:null,statement:'',draft:emptyDataOptions(),applied:emptyDataOptions(),pendingQueries:{},...s})
const tables=computed(()=>s.tables.filter(n=>n.toLowerCase().includes(filter.value.toLowerCase())))
const columns=computed(()=>s.schemas[s.table]||[])
const primary=computed(()=>columns.value.filter(r=>r.key_type==='PRI').map(r=>r.field))
const disabled=computed(()=>props.disabled||pending.value||!props.target)
const dirty=computed(()=>JSON.stringify(s.draft)!==JSON.stringify(s.applied))
async function perform(sql,navigation=false){const feedback=navigation?navigationMessage:message;feedback.value='';pending.value=true;try{return await props.execute({sql})}catch(e){feedback.value=e.message;return null}finally{pending.value=false}}
async function refresh(){const result=await perform('SHOW TABLES',true);if(result){s.tables=(result.rows||[]).map(r=>String(r.table_name));s.tablesLoaded=true;s.tablesLimited=!!result.limit_reached}}
function accept(result,sql){s.result=result;s.statement=sql;if(result.metadata==='schema'){s.schemas[s.table]=result.rows||[];emit('schema',s.schemas[s.table])}else if(!result.metadata&&s.pendingQueries[sql]){s.applied=copyOptions(s.pendingQueries[sql]);delete s.pendingQueries[sql]}}
async function openTable(name){if(disabled.value)return;emit('browse');if(s.table!==name){s.draft=emptyDataOptions();s.applied=emptyDataOptions();s.previous=null;s.result=null}s.table=name;s.offset=0;s.view='data';try{quoteIdentifier(name)}catch(e){message.value=e.message;return}
 if(!s.schemas[name]&&!props.approval){const schema=await perform('DESCRIBE '+quoteIdentifier(name));if(!schema)return;s.schemas[name]=schema.rows||[];emit('schema',s.schemas[name])}
 await loadView('data',0)
}
async function loadView(view,offset=s.offset,options=s.applied){if(!s.table)return;if(s.view!==view)s.result=null;s.view=view;let sql;try{const table=quoteIdentifier(s.table);sql=view==='schema'?'DESCRIBE '+table:view==='indexes'?'SHOW INDEX FROM '+table:tableDataSQL(s.table,columns.value,options,offset)}catch(e){message.value=e.message;return}
 if(view==='data'){s.pendingQueries[sql]=copyOptions(options);s.pendingQueries=Object.fromEntries(Object.entries(s.pendingQueries).slice(-20))}
 const result=await perform(sql);if(result){s.offset=offset;accept(result,sql)}
}
function addCondition(){if(s.draft.conditions.length<10)s.draft.conditions.push({field:columns.value[0]?.field||'',operator:'=',value:''})}
async function apply(){await loadView('data',0,copyOptions(s.draft))}
async function reset(){s.draft=emptyDataOptions();await apply()}
async function sortColumn(field,direction){if(disabled.value||!columns.value.some(c=>c.field===field))return;const options=copyOptions(s.applied);options.direction=direction||((options.order||(primary.value.length===1?primary.value[0]:''))===field&&options.direction==='ASC'?'DESC':'ASC');options.order=field;s.draft.order=field;s.draft.direction=options.direction;await loadView('data',0,options)}
function openSQL(name=s.table){try{emit('sql',name===s.table&&s.view==='data'&&s.statement?s.statement:'SELECT * FROM '+quoteIdentifier(name)+' LIMIT 100')}catch(e){message.value=e.message}}
watch(()=>[s.table,props.target,props.consoleMode],()=>{resultFocused.value=false})
watch(()=>s.restore,restore=>{if(restore){const {result,sql}=restore;delete s.restore;if(result.metadata==='tables'){s.tables=(result.rows||[]).map(r=>String(r.table_name));s.tablesLoaded=true;s.tablesLimited=!!result.limit_reached}else {s.table=result.table||sql.match(/(?:from|describe)\s+`?([A-Za-z_][A-Za-z0-9_]*)/i)?.[1]||'';s.view=result.metadata==='schema'?'schema':result.metadata==='indexes'?'indexes':'data';s.offset=Number(sql.match(/offset\s+(\d+)/i)?.[1]||0);accept(result,sql)}}},{immediate:true})

import OptionPicker from '../shared/components/OptionPicker.vue'

import {TreeRoot,TreeItem} from 'reka-ui'



import {Button,Checkbox,CheckboxGroupRoot,Empty,EmptyContent,EmptyDescription,EmptyHeader,Field,FieldLabel,Input,Popover,PopoverContent,PopoverTrigger,Tabs,TabsContent,TabsList,TabsTrigger,Textarea} from '../shared/shadcn-ui.js'
</script>
<template><section aria-label="数据库表浏览" class="resource-browser database-browser" :class="{'no-target':!target}"><aside v-show="navigationOpen&&!resultFocused&&!!target"><div class="browser-head"><b>{{target?.database||'数据库表'}}</b><Button @click="refresh" variant="outline" size="default" type="button" :disabled="(disabled)">{{pending?'读取中…':approval?'申请读取表列表':'加载表列表'}}</Button></div><Input v-model="filter" placeholder="搜索表名" v-bind="{&quot;aria-label&quot;:&quot;筛选表名&quot;}"/><small v-if="s.tablesLoaded">{{tables.length}} / {{s.tables.length}} 张表<span v-if="s.tablesLimited"> · 仅展示前 1000 张</span></small><p v-if="navigationMessage" role="alert" class="browser-error">{{navigationMessage}}</p><TreeRoot v-slot="{flattenItems}" :items="tables.map(name=>({key:name,title:name}))" :get-key="node=>node.key||''" :model-value="s.table?{key:s.table}:undefined" :disabled="disabled" @update:model-value="node=>{if(node?.key)openTable(node.key)}" class="space-y-1 p-2"><TreeItem v-for="node in flattenItems" :key="node._id" v-bind="node.bind" class="flex min-w-0 cursor-pointer items-center gap-2 rounded-md px-3 py-2 text-sm outline-none hover:bg-accent focus-visible:ring-2 focus-visible:ring-ring data-selected:bg-accent"><span class="min-w-0 flex-1 truncate" :title="node.value.title">{{node.value.title}}</span><Button variant="ghost" size="xs" :disabled="disabled" :aria-label="'查询 '+node.value.title" @click.stop="openSQL(node.value.title)">SQL</Button></TreeItem></TreeRoot><p v-if="!s.tablesLoaded" class="empty">点击上方按钮加载表列表。</p><p v-else-if="!tables.length" class="empty">没有匹配的表。</p></aside><Button v-if="navigationOpen&&!resultFocused&&!!target" aria-label="收起表导航" @click="emit('close-navigation')" class="navigator-backdrop" variant="outline" size="default" type="button"></Button><div v-show="consoleMode" class="browser-detail console-detail"><slot name="console"/></div><div v-show="!consoleMode" class="browser-detail data-detail"><div v-if="s.table" v-show="!resultFocused" class="browser-head"><b>{{s.table}}</b><div class="database-view-tools flex min-w-0 items-center gap-2"><Tabs class="section-tabs min-w-0" :model-value="s.view" @update:model-value="(value=>loadView(value,value==='data'?0:s.offset))($event)"><div class="flex min-w-0 items-center gap-2"><TabsList class="h-auto! max-w-full flex-wrap gap-y-1 [&>[data-slot=tabs-trigger]]:h-7"><TabsTrigger v-for="v in [{id:'data',label:'数据'},{id:'schema',label:'结构'},{id:'indexes',label:'索引'}]" :disabled="disabled" :value="v.id">{{v.label}}</TabsTrigger></TabsList></div><TabsContent v-for="v in [{id:'data',label:'数据'},{id:'schema',label:'结构'},{id:'indexes',label:'索引'}]" :disabled="disabled" :value="v.id" force-mount v-show="!(s.view!==v.id)" class="min-w-0"></TabsContent></Tabs><Button @click="loadView(s.view)" variant="outline" size="default" type="button" :disabled="(disabled)">{{approval?'申请刷新':'刷新'}}</Button><Button @click="openSQL()" variant="outline" size="default" type="button" :disabled="(disabled)">在 SQL 查询中打开</Button></div></div><p v-if="message" role="alert" class="browser-error">{{message}}</p><Empty v-if="!s.table" class="browser-empty"><EmptyHeader><EmptyDescription>{{!target?'请在上方选择连接和数据库，或选择应用与逻辑资源。':!s.tablesLoaded?'点击“加载表列表”，或切换到“SQL 查询”编写查询。':'从左侧选择表查看数据，或切换到“SQL 查询”编写查询。'}}</EmptyDescription></EmptyHeader></Empty><template v-else><section v-if="s.view==='data'" v-show="!resultFocused" aria-label="表数据筛选" class="data-controls"><div class="filter-toolbar"><Button @click="s.draft.filterMode='fields';addCondition()" variant="outline" size="sm" type="button" :disabled="(disabled||!columns.length||s.draft.conditions.length>=10)">＋ 条件</Button><Button :class="{selected:s.draft.filterMode==='sql'}" @click="s.draft.filterMode=s.draft.filterMode==='sql'?'fields':'sql'" variant="outline" size="sm" type="button" :disabled="(disabled)">WHERE 条件</Button><Popover><PopoverTrigger as-child><Button variant="outline" size="sm" type="button" :disabled="(disabled||!columns.length)">字段 {{s.draft.fields.length?s.draft.fields.length+' 个':'全部'}}</Button></PopoverTrigger><PopoverContent class="max-h-[80dvh] max-w-[calc(100vw-2rem)] overflow-auto" align="end" :style="{maxHeight:'min(360px,65vh)',overflow:'auto',maxWidth:'min(420px,85vw)'}"><div class="column-options"><Button @click="s.draft.fields=[]" variant="outline" size="sm" type="button" :disabled="(disabled)">选择全部字段</Button><CheckboxGroupRoot v-model="s.draft.fields" direction="vertical" class="flex flex-wrap items-center gap-3"><FieldLabel class="flex items-center gap-2 font-normal" v-for="col in columns" :key="col.field"><Checkbox   :value="col.field" :disabled="disabled||(!s.draft.fields.includes(col.field)&&s.draft.fields.length>=50)"/>{{col.field}}</FieldLabel></CheckboxGroupRoot><small>未勾选表示全部字段，最多选择 50 个字段。</small></div></PopoverContent></Popover><Field orientation="horizontal" class="w-auto gap-2"><FieldLabel as="div">排序 </FieldLabel><OptionPicker v-model="s.draft.order" aria-label="排序字段" style="width:132px" :disabled="disabled" :options="[{value:&quot;&quot;,label:String(primary.length?'主键':'不排序')},...(columns).map((col)=>({value:col.field,label:String(col.field)}))]"/></Field><OptionPicker v-model="s.draft.direction" aria-label="排序方向" style="width:82px" :disabled="disabled" :options="[{value:&quot;ASC&quot;,label:&quot;升序&quot;},{value:&quot;DESC&quot;,label:&quot;降序&quot;}]"/><Field orientation="horizontal" class="w-auto gap-2"><FieldLabel as="div">每页 </FieldLabel><OptionPicker v-model.number="s.draft.size" aria-label="每页行数" style="width:80px" :disabled="disabled" :options="[...([50,100,200,500,1000]).map((n)=>({value:n,label:String(n)}))]"/></Field><div class="filter-actions"><Button @click="apply" variant="default" size="sm" type="button" :disabled="(disabled)">{{approval?'申请筛选':'应用筛选'}}</Button><Button @click="reset" variant="outline" size="sm" type="button" :disabled="(disabled)">重置</Button></div></div><div v-if="s.draft.filterMode==='fields'&&s.draft.conditions.length" class="filter-rows"><Field v-if="s.draft.conditions.length>1" class="filter-logic"><FieldLabel as="div">匹配 </FieldLabel><OptionPicker v-model="s.draft.logic" aria-label="条件关系" :disabled="disabled" class="min-w-36" :options="[{value:&quot;AND&quot;,label:&quot;全部条件（AND）&quot;},{value:&quot;OR&quot;,label:&quot;任一条件（OR）&quot;}]"/></Field><div v-for="(condition,i) in s.draft.conditions" :key="i" class="filter-row"><OptionPicker v-model="condition.field" :aria-label="'筛选字段 '+(i+1)" :disabled="disabled" class="min-w-36" :options="[...(columns).map((col)=>({value:col.field,label:String(col.field)}))]"/><OptionPicker v-model="condition.operator" :aria-label="'筛选运算 '+(i+1)" :disabled="disabled" class="min-w-36" :options="[...(filterOperators).map((op)=>({value:op,label:String(op)}))]"/><Input v-if="!condition.operator.includes('NULL')" v-model="condition.value" :placeholder="condition.operator.includes('IN')?'多个值以逗号分隔':condition.operator.includes('LIKE')?'例如 %关键词%':'条件值（空白表示空字符串）'" :disabled="disabled" @keydown.enter.prevent="apply" v-bind="{&quot;aria-label&quot;:('筛选值 '+(i+1))}"/><Button :aria-label="'删除条件 '+(i+1)" @click="s.draft.conditions.splice(i,1)" variant="outline" size="default" type="button" :disabled="(disabled)">×</Button></div></div><Textarea v-else-if="s.draft.filterMode==='sql'" v-model="s.draft.where" placeholder="例如：status = 1 AND name LIKE '%关键词%'" :disabled="disabled" @keydown="e=>{if(e.key==='Enter'&&(e.ctrlKey||e.metaKey)){e.preventDefault();apply()}}" v-bind="{&quot;aria-label&quot;:&quot;WHERE 条件&quot;}" :rows="4"/><div v-if="dirty||s.applied.where||s.applied.conditions.length||!primary.length||!columns.length" class="filter-status"><span v-if="dirty" class="pending-filter">条件尚未应用</span><span v-else>{{s.applied.filterMode==='sql'&&s.applied.where?'WHERE 条件已应用':s.applied.conditions.length?s.applied.conditions.length+' 条条件已应用':'未设置筛选条件'}}</span><small v-if="!primary.length">未读取到主键，分页顺序可能变化。</small><Button v-if="!columns.length" @click="loadView('schema')" variant="outline" size="default" type="button" :disabled="(disabled)">{{approval?'申请表结构以选择字段':'读取表结构以选择字段'}}</Button></div></section><QueryResults expandable :focused="resultFocused" @focus="resultFocused=!resultFocused" :result="s.result" :previous="s.previous" :sortable="s.view==='data'" :sort-field="s.applied.order||(primary.length===1?primary[0]:'')" :sort-direction="s.applied.direction" @sort="sortColumn" @pin="s.previous=JSON.parse(JSON.stringify(s.result))"/><p v-if="pending" role="status" class="loading-status">正在读取…</p><div v-if="s.result&&s.view==='data'" class="browser-pagination"><Button @click="loadView('data',Math.max(0,s.offset-s.applied.size))" variant="outline" size="default" type="button" :disabled="(disabled||s.offset===0)">上一页</Button><span>第 {{Math.floor(s.offset/s.applied.size)+1}} 页 · 返回 {{s.result.rows?.length||0}} 行</span><Button @click="loadView('data',s.offset+s.applied.size)" variant="outline" size="default" type="button" :disabled="(disabled||!s.result.limit_reached||s.result.truncated||s.offset+s.applied.size>10000)">下一页</Button><small v-if="s.offset+s.applied.size>10000">深分页请使用 SQL 主键范围查询。</small></div></template></div></section></template>
<style src="./browser.css"></style>

<style scoped>.browser-empty{display:flex;flex:1;flex-direction:column;align-items:center;justify-content:center;min-height:180px}</style>
